const e=[{id:1,code:"MIL-101",icon:"Siren",accent:"#dc2626",title:"Rapid Response",subtitle:"Rapid Emergency Response",summary:"Procedures for rapid response during emergency incidents",blocks:[{body:"In military situations, speed of response saves lives. Readiness and continuous training are essential."},{heading:"1. Situation Assessment (SALUTE)",body:"Rapid report:",points:["S - Size: number and size","A - Activity: what they are doing","L - Location: the place (coordinates)","U - Unit: unit or type","T - Time: the time","E - Equipment: equipment and materiel"]},{heading:"2. Fire Response",body:"On a military base:",points:["Alert: siren or shouting, and call 115 immediately","Firefighting team: act quickly, only on small fires and away from ammunition and explosives","Evacuation: in an orderly manner","Assembly: at the designated assembly point, upwind and outside the danger area","Headcount: every person must be accounted for"]},{heading:"3. Field First Aid",body:"First aid in the field:",points:["Life-threatening bleeding from an arm or leg: apply a tourniquet immediately and write down the time it was applied","Fractures: immobilize the limb and do not move it","Burns: cool for 20 minutes with cool running water","CPR: 30:2 (if you are not trained, chest compressions only), and call 122"]}],media:[{kind:"video",src:"media/videos/mil_response.mp4",title:"Rapid Response",description:"Key procedures"}],quiz:[{question:"In SALUTE, what does the letter L stand for?",options:[{text:"Light",correct:!1},{text:"Location",correct:!0},{text:"Length",correct:!1},{text:"List",correct:!1}],explanation:"L = Location: the place and its coordinates."}]},{id:2,code:"MIL-102",icon:"Tent",accent:"#16a34a",title:"Setting Up a Camp",subtitle:"Safe Camp Setup",summary:"Setting up a military camp safely",blocks:[{body:"A military camp must be protected from both natural and man-made hazards."},{heading:"1. Site Selection",body:"A suitable site:",points:["High ground: not in gullies or valleys (flood risk)","Close to water, but not too close","Sheltered from the wind, but not under large trees (falling branches and lightning)","Access and exit routes: clear and open"]},{heading:"2. Camp Layout",body:"Main areas:",points:["Tents: in rows, with spacing between them","Fire area: away from the tents","Latrines (toilets): away from water and food, and downwind","First aid point: in the center of the camp"]},{heading:"3. Camp Safety",body:"Important rules:",points:["Fires: continuous watch (24 hours)","Electricity: generators must be kept away from tents (risk of CO gas)","Fuel: in a dedicated, separate location","Fire extinguishers: near the tents and fire areas"]}],media:[{kind:"image",src:"media/images/mil_camp.png",title:"Camp",description:"Layout"}],quiz:[{question:"Where should the fire area be?",options:[{text:"Near the tents",correct:!1},{text:"Away from the tents",correct:!0},{text:"Inside a tent",correct:!1},{text:"Anywhere",correct:!1}],explanation:"Away from the tents, so that the fire does not spread to them."}]},{id:3,code:"MIL-103",icon:"HeartPulse",accent:"#dc2626",title:"Field First Aid (MARCH)",subtitle:"Tactical First Aid",summary:"First aid in field conditions: the MARCH sequence",blocks:[{body:"Field first aid differs from ordinary first aid: speed and the order of actions matter more. The MARCH sequence from Tactical Combat Casualty Care (TCCC) saves lives."},{heading:"1. The MARCH Sequence",body:"Order of first aid actions:",points:["M - Massive Hemorrhage: life-threatening bleeding comes first; direct pressure, wound packing, tourniquet","A - Airway: open the airway","R - Respiration: check breathing and look for chest wounds","C - Circulation: blood circulation and signs of shock","H - Hypothermia / Head Injury: keep the casualty warm and check for head injuries"]},{heading:"2. Tourniquet",body:"For life-threatening bleeding from an arm or leg:",points:["Position: 5-7 cm above the wound, not over a joint","Tightening: turn the windlass until the bleeding stops","Time: write the time of application on the tourniquet or on the casualty's forehead","Never loosen it in the field; only the medical team at the hospital may remove it","Evacuate the casualty quickly (MEDEVAC) and tell the medical team the time of application"]},{heading:"3. Recovery Position",body:"For an unconscious person who is breathing normally and has no suspected neck or back injury:",points:["1. Roll the casualty onto their side","2. Place their upper hand under their cheek","3. Bend the knee of the upper leg so that they do not roll onto their stomach","4. Tilt the head slightly back so that the airway stays open","5. Keep checking breathing until help arrives (122 or MEDEVAC)"]},{heading:"4. Burns",body:"Treating burns in the field:",points:["Cooling: 20 minutes with clean, cool running water","Covering: sterile gauze or clean plastic wrap, without wrapping tightly","Do not use ice!","Do not use creams, oil or toothpaste; do not burst blisters","Large burns, or burns to the face, hands or joints: evacuate quickly (122 or MEDEVAC)"]}],media:[{kind:"video",src:"media/videos/mil_tourniquet.mp4",title:"Tourniquet",description:"How to use it"},{kind:"image",src:"media/images/mil_recovery.png",title:"Recovery Position",description:"For an unconscious casualty who is breathing"}],quiz:[{question:"In the MARCH sequence, what comes first?",options:[{text:"Breathing",correct:!1},{text:"Life-threatening bleeding",correct:!0},{text:"The heart",correct:!1},{text:"Cold",correct:!1}],explanation:"M comes first, because in the field bleeding is the leading cause of preventable death."},{question:"When do we use a tourniquet?",options:[{text:"For all wounds",correct:!1},{text:"Life-threatening bleeding from an arm or leg",correct:!0},{text:"Head wounds",correct:!1},{text:"Abdominal wounds",correct:!1}],explanation:"Only for life-threatening bleeding from the arms and legs; write down the time of application and never loosen it in the field."}]},{id:4,code:"MIL-104",icon:"Radio",accent:"#2563eb",title:"Emergency Communications",subtitle:"Communicating in an Emergency",summary:"Communication systems during emergencies",blocks:[{body:"Good communication is the key to success. In disasters, communication networks may stop working."},{heading:"1. Communication Systems",body:"Means of communication:",points:["Radio: the primary means, always ready","Mobile phone: if there is network coverage","Satellite: for remote locations","Light: visual signals","Sound: sirens, whistles, shouting"]},{heading:"2. The Correct Message",body:"How to pass a message:",points:["Location: accurate coordinates","Situation: what has happened","Numbers: how many people and how many casualties","Needs: what is required","Repetition: to confirm the message"]},{heading:"3. Emergency Codes",body:"Examples of color codes (codes differ from one organization to another; follow your command's instructions):",points:["Code Red: fire","Code Blue: medical emergency","Code Black: explosive threat","Code Yellow: warning and standby","Code Green: safe, the situation is over"]}],media:[{kind:"video",src:"media/videos/mil_radio.mp4",title:"Radio",description:"Using the radio"}],quiz:[{question:"What does Code Red mean?",options:[{text:"Safe",correct:!1},{text:"Medical emergency",correct:!1},{text:"Fire",correct:!0},{text:"Warning",correct:!1}],explanation:"Code Red = fire."}]},{id:5,code:"MIL-105",icon:"Biohazard",accent:"#ca8a04",title:"Protection Against CBRN Hazards",subtitle:"Chemical, Biological, Radiological, Nuclear",summary:"Protection against chemical, biological, radiological and nuclear hazards",blocks:[{body:"Chemical, biological, radiological and nuclear (CBRN) hazards are a real threat to military forces and civilians. Peshmerga must recognize these hazards and know how to protect themselves."},{heading:"1. Chemical Hazard (C)",body:"Chemical agents:",points:["Nerve agents (such as Sarin and VX): the most lethal","Choking agents (such as Chlorine and Phosgene): damage the lungs","Blister agents (such as Mustard): burn the skin, eyes and lungs","Tear gas (CS): used in training to test the mask","Signs: tears, runny nose, chest tightness, coughing, an unusual smell","Action: put on your mask immediately, raise the alarm, and leave the area upwind (toward the direction the wind is coming from) and to high ground"]},{heading:"2. Biological Hazard (B)",body:"Biological agents:",points:["Anthrax: a bacterium; it may appear as a white powder","Plague: a bacterium; the pneumonic form spreads from person to person through the air","Smallpox: a virus; spreads quickly","Signs: fever, coughing, weakness; they appear after several days or weeks","Protection: mask, gloves, keeping away from the sick, and health monitoring","Treatment: antibiotics or vaccine, as decided by a doctor"]},{heading:"3. Radiological (R) and Nuclear (N)",body:"The hazard of radioactive radiation:",points:["Dirty bomb: explosives + a radioactive material","Nuclear: the detonation of a nuclear weapon","Protection: Time + Distance + Shielding","Shielding: thick walls, concrete, earth","Decontamination: remove your outer clothing and wash your body with water and soap","Time: the less time you spend nearby, the better"]},{heading:"4. Protective Equipment (PPE)",body:"MOPP (Mission Oriented Protective Posture) levels: each level adds an item to the level before it:",points:["A gas mask with a CBRN filter, together with protective clothing, boots and gloves, must always be at hand","MOPP 1: the protective overgarment is worn","MOPP 2: MOPP 1 + protective overboots","MOPP 3: MOPP 2 + the gas mask and its hood","MOPP 4: MOPP 3 + gloves: full protection","Atropine auto-injector: for nerve agent poisoning, according to medical instructions; and continuous training on MOPP"]}],media:[{kind:"video",src:"media/videos/mil_cbrn.mp4",title:"CBRN",description:"Recognition and protection"},{kind:"image",src:"media/images/mil_mopp.png",title:"MOPP Levels",description:"4 levels"}],quiz:[{question:"What does CBRN stand for?",options:[{text:"Computer",correct:!1},{text:"Chemical, Biological, Radiological, Nuclear",correct:!0},{text:"Communications",correct:!1},{text:"First aid",correct:!1}],explanation:"Chemical, Biological, Radiological, Nuclear."},{question:"What are the three factors of protection against radiation?",options:[{text:"Water, food, air",correct:!1},{text:"Time, distance, shielding",correct:!0},{text:"Running, pressure, heat",correct:!1},{text:"Radio, mobile phone, satellite",correct:!1}],explanation:"Short time, greater distance and thick shielding (Time, Distance, Shielding)."},{question:"What is Atropine used for?",options:[{text:"Burns",correct:!1},{text:"Bleeding",correct:!1},{text:"Nerve agent poisoning",correct:!0},{text:"Fractures",correct:!1}],explanation:"Atropine is a drug against nerve agent poisoning."}]},{id:6,code:"MIL-106",icon:"Bomb",accent:"#ea580c",title:"The Danger of Mines and IEDs",subtitle:"Mine Awareness & IED Safety",summary:"Recognizing the danger of mines and improvised explosive devices (IEDs) and protecting yourself",blocks:[{body:"Mines and improvised explosive devices are a clear danger in the Kurdistan Region. This danger does not threaten soldiers alone: civilians also become victims."},{heading:"1. Types of Mines",body:"Main mine types:",points:["Anti-personnel mine (AP): detonated by the pressure of a foot","Anti-tank/anti-vehicle mine (AT): needs greater pressure","Tripwire mine: a thin wire that is hard to see","Claymore: detonated remotely","Cluster munitions: small and colorful; children see them as toys!",'Signs of a minefield: red signs (a skull or the word "Mines"), red-painted stones, surrounding wire fences; never cross them']},{heading:"2. IEDs: Improvised Explosive Devices",body:"Types:",points:["RCIED: detonated by remote control or mobile phone","VOIED: detonated when the victim touches it or steps on it","Timed IED: detonated by a clock (timer)","VBIED: a vehicle packed with explosives","Signs: unfamiliar wires, an abandoned vehicle, freshly dug earth","If you see one: do not approach! Move away and report it"]},{heading:"3. The 5Cs of IEDs",body:"5 steps:",points:["1. Confirm: confirm from a distance; do not approach and do not touch","2. Clear: move everyone away, at least 300 m","3. Call: report to your command and the EOD team, and call 115","4. Cordon: seal off the area and watch out for a secondary device","5. Control: control the area until the EOD team arrives","Distance: at least 300 m for an IED; more for a VBIED: about 600 m for a small car and up to 2800 m for a large truck"]},{heading:"4. Civilian Awareness",body:"Educating the public:",points:["Children: do not touch unknown objects!","Farmers and builders: ask the authorities before digging; a place without warning signs is not necessarily safe, because most dangerous areas are not marked","Shepherds: do not graze livestock in mined areas","Learn to recognize mine warning signs; respect them and never remove them","If you see a mine or any strange object: do not go closer, warn others and keep them away, remember the place and report it to the authorities; in an emergency call 115","Never touch or pick one up: it means death!","If you realize you may be in a mined area: stop at once, stay still and do not move your feet, call for help and wait for a trained team to arrive"]}],media:[{kind:"video",src:"media/videos/mil_mine.mp4",title:"Mines and IEDs",description:"Recognition and self-protection"},{kind:"image",src:"media/images/mil_mine_types.png",title:"Types of Mines",description:"Pictures"}],quiz:[{question:"If you see an IED, what will you do?",options:[{text:"Go closer to it",correct:!1},{text:"Touch it",correct:!1},{text:"Move away and report it",correct:!0},{text:"Get close and take a photo",correct:!1}],explanation:"Move away, move people away, and inform your command and the EOD team."},{question:"What is the safe distance from a vehicle-borne bomb (VBIED)?",options:[{text:"100 m",correct:!1},{text:"300 m",correct:!1},{text:"At least 600 m for a small car, and more for larger vehicles",correct:!0},{text:"50 m if you are behind a wall",correct:!1}],explanation:"According to the CISA and FBI bomb threat stand-off chart: about 600 m for a small car, about 730 m for a van or SUV, and 1200-2800 m for large trucks."},{question:"Why are cluster munitions dangerous for children?",options:[{text:"Because they are large",correct:!1},{text:"They are small and colorful: they look like toys",correct:!0},{text:"Because they do not explode",correct:!1},{text:"Because they only kill soldiers",correct:!1}],explanation:"They are small and colorful, and children pick them up as toys."}]},{id:7,code:"MIL-107",icon:"Compass",accent:"#0d9488",title:"Survival and Navigation",subtitle:"Survival Skills & Navigation",summary:"Field survival skills, navigation and rescue",blocks:[{body:"In field conditions, a Peshmerga may become separated from their team. Water, fire, shelter and direction are the four pillars of survival."},{heading:"1. Water: The First Priority",body:"In general, a person survives about 3 days without water, and less in the heat:",points:["Sources: rivers, springs, rain, dew","Boiling: 1 minute at a rolling boil (above 2000 m altitude: 3 minutes)","Purification tablets: chlorine or iodine, following the instructions on the packet","Filtering: filter through a clean cloth, then boil","Do not drink stagnant water without purifying it","Always carry a bottle of water with you"]},{heading:"2. Fire",body:"Fire = warmth + light + signaling:",points:["The fire triangle: fuel + oxygen + heat","Dry wood: start with small twigs","Lighting: a lighter, matches, or flint and steel","Leave gaps between the pieces of wood so that air can reach the fire","Choose a spot cleared of dry grass and ring the fire with stones","Three fires in a triangle = a distress signal (SOS)"]},{heading:"3. Shelter",body:"Protection from the weather:",points:["Caves: the best shelters, but beware of rockfalls and animals","Tree branches and boughs","Rocks and earth","The shelter entrance must not face the wind","A fire near the shelter, but at a safe distance","Protect yourself from the cold of the ground (put branches, grass or cardboard underneath you)"]},{heading:"4. Navigation",body:"Without GPS:",points:["Compass: direction and azimuth","The sun: rises in the east and sets in the west","The North Star (Polaris): shows the direction of north","Moss on trees is not a reliable sign for finding north","Water flows downhill; follow a river toward villages and roads","Three sounds, three fires or three lights = a distress signal (SOS)"]}],media:[{kind:"video",src:"media/videos/mil_survival.mp4",title:"Survival",description:"Core skills"}],quiz:[{question:"In general, how many days can a person survive without water?",options:[{text:"1",correct:!1},{text:"3",correct:!0},{text:"7",correct:!1},{text:"14",correct:!1}],explanation:"About 3 days (the rule of threes); in the heat the time is much shorter."},{question:"What do three fires in a triangle mean?",options:[{text:"Protection",correct:!1},{text:"SOS: a request for help",correct:!0},{text:"A fire outbreak",correct:!1},{text:"They have no meaning",correct:!1}],explanation:"It is an international signal requesting help (SOS)."}]},{id:8,code:"MIL-108",icon:"Truck",accent:"#4b5563",title:"Vehicle and Convoy Safety",subtitle:"Vehicle & Convoy Safety",summary:"Safety in military transport and convoys",blocks:[{body:"Traffic accidents, ambushes and improvised explosive devices (IEDs) on the roads are the main hazards."},{heading:"1. Military Driving Rules",body:"Principles:",points:["Always wear a helmet","Do not overload open vehicles with passengers","Seat belts for all occupants","Radio: continuous communication","In dangerous areas, use only cleared routes and do not leave the road","At night: vehicle lights according to command instructions"]},{heading:"2. Convoy Organization",body:"Rules:",points:["Spacing between vehicles: 50-100 m, as ordered by the convoy commander","One radio in every vehicle","Medical vehicle: at the rear","Recovery (repair) vehicle: in the middle","Lead vehicle: 500 m ahead","Briefing before departure"]},{heading:"3. Ambush",body:"If the convoy is ambushed:",points:["Drive quickly out of the area: do not stop!","Send a SALUTE report quickly","Identify the direction of the attack","MARCH for casualties once the location is secure","Request backup","Watch out for a secondary IED on the road"]},{heading:"4. Traffic Accidents",body:"What to do:",points:["Stop in a safe place","Place the warning triangle","MARCH for casualties","Call 115 and 122","Fire: move everyone away and stay upwind; if a vehicle carrying explosives is involved in the fire (ERG Guide 112, Divisions 1.1, 1.2, 1.3, 1.5): isolate and evacuate 1600 m (1 mile) in all directions, emergency responders included; if the fire reaches the cargo, do not fight it","Take photos and write a report"]}],media:[{kind:"video",src:"media/videos/mil_convoy.mp4",title:"Convoy",description:"Organization"}],quiz:[{question:"According to this lesson, what is the normal spacing between convoy vehicles?",options:[{text:"10 m",correct:!1},{text:"50-100 m",correct:!0},{text:"2 m",correct:!1},{text:"500 m",correct:!1}],explanation:"50-100 m, depending on the situation and the convoy commander's orders."},{question:"During an ambush, what will the driver do?",options:[{text:"Stop",correct:!1},{text:"Drive quickly out of the area",correct:!0},{text:"Get out of the vehicle",correct:!1},{text:"Stop to take photos",correct:!1}],explanation:"Drive quickly out of the ambush area, if the road is open."}]},{id:9,code:"MIL-109",icon:"Droplets",accent:"#0284c7",title:"Water Purification and Personal Hygiene",subtitle:"Water Purification & Hygiene",summary:"Water purification and personal hygiene in the field",blocks:[{body:"Diseases from contaminated water can be more dangerous than the enemy! Contaminated water weakens forces."},{heading:"1. Water Purification",body:"4 methods:",points:["Boiling: 1 minute at a rolling boil; the most reliable way to kill germs","Chlorine/iodine tablets: follow the instructions on the packet, and wait 30 minutes","Special filters (such as LifeStraw)","SODIS: clear plastic bottles, 6 hours in direct sunlight (if it is cloudy: 2 days)","Do not drink stagnant water without purifying it","Order: first let the sediment settle, then filter, then purify"]},{heading:"2. Personal Hygiene",body:"In the field:",points:["Handwashing: before eating and after using the latrine","Clean your body regularly; if water is scarce, use a damp cloth","Change your socks daily and keep your clothes clean","Keep your feet clean and dry","Minor wounds: wash them and cover them with a clean dressing","Brush your teeth twice a day"]},{heading:"3. Food",body:"Food safety:",points:["Check the expiry date","Cook food thoroughly (75°C at the center)","Do not leave cooked food at room temperature for more than 2 hours (above 32°C: 1 hour)","Cover food to protect it from flies and dust","Burn or bury food waste away from the camp","Drink plenty of clean water"]},{heading:"4. Field Illnesses",body:"Common ones:",points:["Diarrhea: drink a water, salt and sugar solution (ORS)","Malaria: mosquito nets and insect repellent spray","Heat stroke: shade, rapid cooling, and call 122","Hypothermia: rewarm gradually and remove wet clothing","Infection: change the dressing daily, or whenever it becomes wet or dirty","Report any illness to the medic"]}],media:[{kind:"video",src:"media/videos/mil_water.mp4",title:"Water",description:"Purification"}],quiz:[{question:"What is the most reliable method of purifying water?",options:[{text:"Tablets",correct:!1},{text:"Boiling",correct:!0},{text:"A filter",correct:!1},{text:"Sunlight",correct:!1}],explanation:"Boiling for 1 minute at a rolling boil is the most reliable way to kill disease-causing germs."},{question:"For how many hours can cooked food stay at room temperature?",options:[{text:"12 hours",correct:!1},{text:"No more than 2 hours (above 32°C: 1 hour)",correct:!0},{text:"24 hours",correct:!1},{text:"It makes no difference",correct:!1}],explanation:"According to WHO guidance, do not leave cooked food at room temperature for more than 2 hours; above 32°C, 1 hour (USDA)."}]},{id:10,code:"MIL-110",icon:"Thermometer",accent:"#ea580c",title:"Heat and Cold: Weather Hazards",subtitle:"Heat & Cold Weather Operations",summary:"Heat and cold hazards and how to protect yourself",blocks:[{body:"In the Kurdistan Region, summer temperatures reach about 50°C, and in winter the mountains can drop below -15°C."},{heading:"1. Heat Hazards",body:"Heat stroke kills:",points:["Heat exhaustion: headache, nausea, vomiting, heavy sweating","Heat stroke: body temperature of 40°C or higher and altered mental state: an emergency! Cool immediately and call 122","Water: about 1 liter per hour during heavy work; no more than 1.4 liters per hour","Work and rest cycles according to the heat index (WBGT); rest in the shade","Heat stroke cooling: at once, before transport; best is the whole body up to the neck in cold water for 15 minutes or until the casualty thinks clearly again, whichever comes first; if not possible: cold shower, cold wet towels or sheets, ice packs and fanning; nothing to drink while confused","Light-colored, lightweight clothing"]},{heading:"2. Cold Hazards",body:"Hypothermia and frostbite:",points:["Hypothermia: body temperature below 35°C","Frostbite: freezing of the fingers, ears and nose","Layered clothing","Rewarm gradually, not with direct fire","Frostbite: do not rub! Place it in warm water (37-39°C), only if it will not freeze again","If shivering stops and the person becomes confused, it is an emergency! Call 122"]},{heading:"3. Layered Clothing",body:"The three-layer system:",points:["1. Layer next to the skin (base layer): wicks sweat away from the body","2. Insulating layer (insulation): such as fleece","3. Outer layer (shell): against wind and rain","Thick gloves","Hat and scarf: heat is lost from any uncovered part of the body, not only the head; cover the whole body","Waterproof boots"]}],media:[{kind:"video",src:"media/videos/mil_weather.mp4",title:"Weather",description:"Heat and cold"}],quiz:[{question:"During heavy work in the heat, about how much water do you drink per hour?",options:[{text:"Only when you are thirsty",correct:!1},{text:"About 1 liter (no more than 1.4 liters)",correct:!0},{text:"2 liters",correct:!1},{text:"3 liters",correct:!1}],explanation:"According to US Army guidance (TB MED 507): about 1 liter per hour during heavy work; more than 1.4 liters per hour can lower the body's salt level."},{question:"With frostbite, which action is wrong?",options:[{text:"Rubbing the frozen area or putting snow on it",correct:!0},{text:"Placing it in warm water (37-39°C)",correct:!1},{text:"Removing wet and tight clothing",correct:!1},{text:"Taking the casualty to a warm place",correct:!1}],explanation:"Rubbing, snow and direct fire damage the skin; rewarm with warm water (37-39°C)."}]},{id:11,code:"MIL-111",icon:"Ambulance",accent:"#dc2626",title:"Casualty Evacuation (MEDEVAC)",subtitle:"Casualty Evacuation & 9-Line",summary:"Safe evacuation and the 9-Line MEDEVAC request",blocks:[{body:"First aid is the first step, but rapid evacuation to hospital saves lives."},{heading:"1. Carrying Casualties",body:"Techniques:",points:["Two-person carry: one at the head end and one at the feet","Fireman carry (over the shoulder): by one person; fast","Stretcher: by 4 people; the best option","Improvised stretcher: 2 poles and a jacket or a blanket","Suspected neck or back injury: do not move the casualty unless there is a risk of fire or explosion","Move the head, neck and back together, in one line"]},{heading:"2. 9-Line MEDEVAC",body:"9 lines:",points:["Line 1: pickup location (coordinates / GPS)","Line 2: radio frequency and call sign","Line 3: number of casualties by precedence (Urgent, Priority, Routine)","Line 4: special equipment (such as a hoist)","Line 5: number of casualties by type: L on a stretcher (litter), A able to walk (ambulatory)","Line 6: security at the pickup site: N no enemy, P possible enemy, E enemy present, X armed escort required","Line 7: method of marking the site (panel, colored smoke, light)","Line 8: nationality and status of casualties (military, civilian, prisoner)","Line 9: CBRN contamination in wartime; or a description of the site terrain in peacetime"]},{heading:"3. Helicopter Landing Zone (LZ)",body:"For the helicopter:",points:["Size: a circle at least 35 m in diameter for a light helicopter (such as the UH-1), 50 m for the UH-60, and 80 m for cargo helicopters","No wires, trees or tall obstacles; level, clear ground","Indicate the wind direction (the helicopter lands into the wind)","At night: 4 lights in an inverted Y","Remove dust and loose light objects from the site, because the rotor wash blows them into the air","Stay 30 m away until you are signaled to approach"]}],media:[{kind:"video",src:"media/videos/mil_medevac.mp4",title:"MEDEVAC",description:"Evacuation"},{kind:"image",src:"media/images/mil_9line.png",title:"9-Line",description:"The form"}],quiz:[{question:"What is the minimum size of a landing zone (LZ) for a light helicopter (such as the UH-1)?",options:[{text:"10 m",correct:!1},{text:"20 m",correct:!1},{text:"35 m",correct:!0},{text:"5 m",correct:!1}],explanation:"A circle 35 m in diameter for a light helicopter; larger helicopters need a larger area (50 m for the UH-60)."},{question:"In the 9-Line, what is Line 1?",options:[{text:"Number of casualties",correct:!1},{text:"Pickup location (coordinates)",correct:!0},{text:"Security at the pickup site",correct:!1},{text:"Radio frequency",correct:!1}],explanation:"Line 1 is the pickup location, given as coordinates."}]},{id:12,code:"MIL-112",icon:"Search",accent:"#d97706",title:"Search and Rescue (SAR)",subtitle:"Search & Rescue Operations",summary:"Operations to search for and rescue people",blocks:[{body:"During earthquakes, floods and explosions, people become trapped under rubble. Peshmerga are often the first to reach the scene."},{heading:"1. Search Methods",body:"Patterns:",points:["Line search: in rows, at regular spacing","Spiral: from the center outward","Sector: the area is divided into sectors","Search dogs (K9)","At set intervals (for example every 10 minutes), call for silence and listen","Call out loudly to people and listen for a reply"]},{heading:"2. Under Rubble",body:"Rescue:",points:["Locate the person: by listening and with search dogs","Talk to the victim and reassure them","Extract them slowly and carefully","Watch out for the danger of a secondary collapse","MARCH immediately for casualties","Call 115 and 122"]},{heading:"3. Water Rescue",body:"Floods and drowning:",points:["Do not enter the water if you have not been trained in rescue","From the bank, reach out or throw something long: a rope, a branch, a long piece of clothing","Put on a life jacket","Human chains only in shallow, slow-moving water","Once the person is out of the water, check their breathing. If they are not breathing normally: call 122 and, if you are trained, start CPR with breaths (drowning stops the breathing first, so breaths matter most); if you are not trained or cannot give breaths, give chest compressions only. Anyone pulled from the water must be checked by a doctor, even if they seem well","15 cm of moving water can knock a person down; 30 cm can carry a car away"]}],media:[{kind:"video",src:"media/videos/mil_sar.mp4",title:"SAR",description:"Search and rescue"}],quiz:[{question:"When searching under rubble, what is done at set intervals (for example every 10 minutes)?",options:[{text:"Everyone runs away",correct:!1},{text:"Silence and listening",correct:!0},{text:"Everyone changes clothes",correct:!1},{text:"Everyone drinks water",correct:!1}],explanation:"All work stops and everyone falls silent, so that the victims' voices can be heard."},{question:"If someone is drowning and you have not been trained in rescue, what will you do?",options:[{text:"Jump into the water",correct:!1},{text:"Reach out or throw something long to them from the bank",correct:!0},{text:"Just watch",correct:!1},{text:"Run away and leave the scene",correct:!1}],explanation:"From the bank, reach out or throw something long to them and call 115; do not go into the water."}]},{id:13,code:"MIL-113",icon:"Flame",accent:"#dc2626",title:"Fire in Military Bases and Ammunition Depots",subtitle:"Fire Safety in Military Bases",summary:"Fire prevention and safe evacuation in military bases and ammunition depots",blocks:[{body:"Fire in military bases is more dangerous, because weapons, ammunition and fuel are stored there. If a fire reaches ammunition or is close to it, there is no firefighting: get out, cordon off the area and call 115."},{heading:"1. Sources of Fire",body:"On bases:",points:["Ammunition and explosives","Gasoline and diesel","Tent heaters","Generators","Smoking","Faulty or overloaded electrical wiring"]},{heading:"2. Fire Extinguishers",body:"Types (classes according to NFPA):",points:["ABC powder: for Classes A, B and C; not for D (metals) or K (cooking oil)","CO₂: for electrical and equipment fires (C) and liquids (B)","An ammunition fire cannot be put out with an extinguisher: get out, cordon off, call 115","P.A.S.S, only when every go/no-go answer is yes (small, new fire; right extinguisher; exit behind you; alarm raised and 115 called; you are trained; no smoke or heat in your way): Pull (the pin), Aim (at the base of the fire), Squeeze, Sweep; if the fire does not go out at once, get out","Place extinguishers near the exit doors","Monthly visual inspection and annual maintenance"]},{heading:"3. Ammunition Depot (Explosives Storage)",body:"Special rules:",points:["Prohibited: cigarettes, open flames, matches, lighters and mobile phones","Protect from heat and direct sunlight, according to the ammunition storage rules","Anti-static clothing and gloves","Fire detection devices and automatic sprinklers","Only authorized personnel may enter","A complete inventory: what, how much and where (to inform 115)"]},{heading:"4. Evacuation Plan",body:"If a fire breaks out in an ammunition depot or near ammunition: do not fight the fire. Get out, cordon off the area and call 115.",points:["Sound the siren and alert everyone","Get out quickly by a route away from the depot (at least 2 exit routes)","Evacuation and cordon area for a depot fire: the distance set by your command's explosives safety rules for that site. The ERG Guide 112 distance, 1600 m (1 mile) in all directions, is for explosives in transport (a truck trailer or rail car in a fire, or fire reaching the cargo); do not use it as the rule for every depot fire","Assembly point: outside the evacuation area, upwind (the side the wind is coming from), behind a barrier, out of the line of sight and away from windows","Headcount: everyone must be accounted for; give the names of missing persons to 115","Call 115 (location, type and quantity of ammunition)"]}],media:[{kind:"video",src:"media/videos/mil_fire_base.mp4",title:"Fire",description:"Military base"}],quiz:[{question:"What is prohibited in an ammunition depot?",options:[{text:"Recording the ammunition inventory",correct:!1},{text:"Cigarettes, open flames and mobile phones",correct:!0},{text:"Talking with colleagues",correct:!1},{text:"Wearing anti-static clothing",correct:!1}],explanation:"Cigarettes, open flames and mobile phones are prohibited, because they can cause a fire or an explosion."},{question:"Under ERG Guide 112, if a truck trailer carrying explosives is involved in a fire, how large must the isolation and evacuation area be?",options:[{text:"50 m",correct:!1},{text:"100 m",correct:!1},{text:"1600 m (1 mile) in all directions, emergency responders included",correct:!0},{text:"300 m",correct:!1}],explanation:"According to ERG Guide 112 (explosives in transport, Divisions 1.1, 1.2, 1.3, 1.5): if a truck trailer or rail car is involved in a fire, isolate and evacuate 1600 m (1 mile) in all directions, emergency responders included; if the fire reaches the cargo, do not fight it and let it burn. For a fire in an ammunition depot, use the distance in your command's explosives safety rules. The assembly point must be outside the evacuation area and upwind."}]},{id:14,code:"MIL-114",icon:"Handshake",accent:"#059669",title:"Cooperation with Civil Defense",subtitle:"Civil-Military Cooperation (CIMIC)",summary:"Cooperation between the Peshmerga and Civil Defense (CIMIC)",blocks:[{body:"In disasters, the Peshmerga and Civil Defense work together."},{heading:"1. Peshmerga Tasks",body:"In disasters:",points:["Search and rescue","Security","Logistics","First aid","Communications","Reconstruction"]},{heading:"2. Coordination with Civil Defense (115)",body:"Communication:",points:["Call 115","A shared communication channel","Incident Command System (ICS)","Emergency Operations Center (EOC)","METHANE report","Inside a city, command belongs to the civilian agencies"]},{heading:"3. Helping the Public",body:"Humanitarian assistance:",points:["Food and water","Tents for displaced people","Field clinics","Transporting people and supplies","Protecting children","Informing the public"]},{heading:"4. Community Awareness",body:"Educating the public:",points:["Safety drills","Mine awareness","Schools","Campaigns","Children: simple teaching","Radio and television"]}],media:[{kind:"video",src:"media/videos/mil_cimic.mp4",title:"CIMIC",description:"Cooperation"}],quiz:[{question:"Inside a city during a disaster, who is in command?",options:[{text:"The military forces",correct:!1},{text:"Civil Defense",correct:!0},{text:"The police",correct:!1},{text:"It makes no difference",correct:!1}],explanation:"The civilian agencies (Civil Defense) are in command, and the military forces provide support."},{question:"What is the role of the Peshmerga in a disaster?",options:[{text:"Only protecting their own bases",correct:!1},{text:"Staying away from the disaster area",correct:!1},{text:"Taking command of all civilian agencies",correct:!1},{text:"Rescue, security, logistics and first aid, in coordination with 115",correct:!0}],explanation:"The Peshmerga provide support in coordination with Civil Defense (115): rescue, security, logistics and first aid."}]},{id:15,code:"MIL-115",icon:"Megaphone",accent:"#9333ea",title:"Public Awareness and Community Information",subtitle:"Community Safety Education",summary:"The role of the Peshmerga in educating the public about safety and civil defense",blocks:[{body:"The Peshmerga's duty is not only combat. Warning the public about hazards saves lives."},{heading:"1. Mine Awareness",body:"Educating the public:",points:["Children: do not touch it, and tell an adult!","Farmers and builders: ask the authorities before digging; a place without warning signs is not necessarily safe","Shepherds: do not graze livestock in mined areas","Teach the signs of mines, and that they must never be removed","If you see a mine or a strange object: do not go closer, keep others away and report it; in an emergency call 115","In an area that may be mined: stop, stay still and do not move your feet, call for help and wait","School lessons"]},{heading:"2. Earthquakes",body:"Teaching:",points:["Drop, Cover, Hold On: under a sturdy table, away from windows","Inspection of buildings","Emergency bag: water (4 liters per person per day, for at least 3 days)","Assembly point","Family emergency plan","Regular drills on the plan"]},{heading:"3. Fire and the Home",body:"Safety:",points:["Gas heaters: good ventilation (risk of CO gas)","Electricity: do not overload sockets","A fire extinguisher in every home","Smoke alarm","Remember the number 115","2 exit routes"]},{heading:"4. First Aid",body:"Basics:",points:["CPR: 30:2, 100-120 compressions per minute, depth 5-6 cm; if you are not trained, chest compressions only (Hands-Only CPR)","Bleeding: firm, direct pressure","Fractures: do not move it; immobilize it","Burns: 20 minutes of cool running water","Poisoning: call 122 and keep the container; do not make the person vomit and give nothing to eat or drink","Write 115 and 122 on the wall"]},{heading:"5. Organizing Campaigns",body:"How:",points:["Plan: topic + objective + area","Team: Peshmerga + Civil Defense (115) + health services","Venues: schools, mosques, villages","Media: posters, videos, social media","Target groups: children, women, officials","Evaluation after the campaign"]}],media:[{kind:"video",src:"media/videos/mil_awareness.mp4",title:"Awareness",description:"Education"},{kind:"image",src:"media/images/mil_campaign.png",title:"Campaign",description:"Organization"}],quiz:[{question:"What is the first lesson for children about mines?",options:[{text:"Pick it up and remove it",correct:!1},{text:"Do not touch it, and tell an adult!",correct:!0},{text:"Go looking for them",correct:!1},{text:"Throw stones at it",correct:!1}],explanation:"Do not touch it, move away and tell an adult; the adult calls 115."},{question:"In every home, what should be written on the wall?",options:[{text:"The name of the homeowner",correct:!1},{text:"115 and 122",correct:!0},{text:"The color of the wall",correct:!1},{text:"Nothing",correct:!1}],explanation:"The emergency numbers: 115 (Civil Defense) and 122 (Ambulance)."},{question:"Where does an awareness campaign reach the most people?",options:[{text:"Only inside the barracks",correct:!1},{text:"In schools, mosques and villages",correct:!0},{text:"In a remote place where nobody lives",correct:!1},{text:"Through a secret letter to one person",correct:!1}],explanation:"A campaign held where people gather (schools, mosques, villages) reaches the most people."}]},{id:16,code:"MIL-116",icon:"FireExtinguisher",accent:"#dc2626",title:"Fire Extinguishers: Complete Training",subtitle:"Fire Extinguisher — Complete Training (PASS)",summary:"Detailed knowledge of all extinguisher types, fire classes and the P.A.S.S procedure",blocks:[{body:"The fire extinguisher is a key piece of equipment for putting out small fires in their early stage. In barracks and military bases, every Peshmerga must be able to use an extinguisher quickly and correctly. Small extinguishers empty quickly, often in a few seconds, and the exact discharge time is on the label, so they must be used quickly and correctly."},{heading:"1. Fire Classes According to NFPA",body:"Under the NFPA system, fires are divided into 5 classes. Classes here use NFPA 10 letters as the project reference; the official system for Duhok is not yet confirmed. EN 2 equivalents: NFPA A = EN A; NFPA B (liquids) = EN B; NFPA B (gases) = EN C; NFPA C (live electrical equipment) has no EN class; NFPA D = EN D; NFPA K = EN F. The classes:",points:["Class A (ordinary solids): wood, paper, fabric, tents. Extinguishers: water, ABC powder, foam.","Class B (flammable liquids and gases): gasoline, kerosene, diesel, oils. Liquids: CO₂, ABC powder, foam. Gas: stop the gas first if it is safe; never put out a gas flame you cannot stop. (Never use water!)","Class C (electrical): generators, panels, switches. Extinguishers: CO₂, clean agent, ABC powder. (Do not use water or foam unless the label shows a Class C rating or an electrical-test marking, as on some water-mist units!)","Class D (metals): magnesium, aluminum. Extinguisher: only a Class D extinguisher or agent whose label lists that metal, not ABC. (Water can cause an explosion!)","Class K (kitchen): cooking oils. Extinguisher: wet chemical, not ABC. (Water spreads the burning oil!)"]},{heading:"2. Types of Extinguishers",body:"Color is not the fire class. Under the European standard BS EN 3 the extinguisher body is red; in the UK a colored band (BS 7863) shows the agent. Other countries use other colors and the color practice in Duhok is not yet confirmed, so always read the label and its class symbols. Classes below are in NFPA letters:",points:["Water extinguisher: all red, no band; for Class A only.","CO₂ extinguisher: black band; for Class B and live electrical equipment (NFPA B and C; under EN 2, C means gas and CO₂ is not rated for gas fires). Short range; not for deep-seated wood or paper fires. Hold only the handle, never the horn: it gets extremely cold and can freeze your hand! In a small room, leave and ventilate after use, because CO₂ pushes out the oxygen.","ABC (dry powder) extinguisher: blue band; for Classes A, B and C; not for D and K. The most common type.","Foam extinguisher: cream band; for Classes A and B. Do not use it on electrical fires!","Clean agent extinguisher: its rating depends on the model, so read the label (often B and C in NFPA letters); for sensitive equipment.","Wet chemical extinguisher: yellow band; for Class K (NFPA K = EN F). Class D extinguisher: its agent must be listed on the label for the metal in use."]},{heading:"3. The P.A.S.S Procedure",body:"Before you use an extinguisher (every answer must be yes): the fire is small and just starting, like a fire in a wastebasket; the extinguisher is the right type; your exit is behind you; the alarm has been raised and 115 called; you are trained; no smoke or heat blocks your way out. If the fire does not go out at once, the extinguisher empties or smoke and heat increase, stop, get out and close the door. Life comes before property. P.A.S.S is the general method for most hand-held extinguishers; Class D, wet chemical, clean agent and wheeled units: follow the label and the manufacturer's instructions:",points:["P = Pull: pull out the safety pin.","A = Aim: aim the nozzle at the base of the fire, not at the flames!","S = Squeeze: squeeze the extinguisher handles firmly.","S = Sweep: sweep the nozzle from left to right until the fire is out."]},{heading:"4. Monthly Extinguisher Inspection",body:"Inspect visually every month (NFPA 10):",points:["Internal pressure: if there is a gauge, its needle must be in the green zone. CO₂ extinguishers have no gauge: lift one to feel that it is full.","Safety pin and its tamper seal: must be in place.","Hose/nozzle: must not be cracked or blocked.","Extinguisher body: must not be rusted or damaged.","Keep these separate: inspection and maintenance once a year by a qualified technician; recharge after any use, even a short one; every 6 years, stored-pressure dry chemical extinguishers that need a 12-year hydrostatic test are emptied and checked inside; hydrostatic test (pressure test of the cylinder) every 5 years for water, foam, CO₂ and stainless-steel dry chemical extinguishers, and every 12 years for stored-pressure dry chemical extinguishers with mild steel, brazed brass or aluminum shells. A test is not a replacement. The rules for Duhok are not yet confirmed."]},{heading:"5. Special Hazards on Military Bases",body:"Military bases are sensitive locations:",points:["Fuel and gasoline: the fuel depot; Class B.","Ammunition depots and explosives: risk of explosion; do not fight the fire! Move away to the distance set by your command's explosives safety rules for that site, cordon off the area and call 115. The ERG Guide 112 distance, 1,600 m (1 mile) in all directions, is for explosives in transport (a vehicle carrying explosives in a fire, or fire reaching the cargo).","Generators and electricity: Class C; CO₂, clean agent or ABC powder; if you can, cut off the power first.","Tents and containers: dry materials; Class A.","Place extinguishers near doors; the travel distance to an extinguisher must not exceed 23 m for Class A, and 9-15 m for Class B (NFPA 10)."]}],media:[{kind:"video",src:"media/videos/mil_fire_ext.mp4",title:"Fire Extinguishers",description:"The P.A.S.S procedure for Peshmerga"}],quiz:[{question:"In NFPA letters, which fire classes is a CO₂ extinguisher rated for?",options:[{text:"A and D",correct:!1},{text:"B and C",correct:!0},{text:"A and K",correct:!1},{text:"D and K",correct:!1}],explanation:"CO₂ is suitable for flammable liquids (B) and electrical equipment (C). Under EN 2, C means gas fires, and CO₂ is not rated for them."},{question:"In the P.A.S.S procedure, where should the extinguisher nozzle be aimed?",options:[{text:"At the top of the flames",correct:!1},{text:"At the base of the fire",correct:!0},{text:"Away from the fire",correct:!1},{text:"At the ceiling",correct:!1}],explanation:"Always aim the nozzle at the base of the fire."},{question:"Why is water not poured on an oil fire (Class K)?",options:[{text:"It does nothing",correct:!1},{text:"Water spreads the burning oil and causes an explosion",correct:!0},{text:"The oil absorbs the water",correct:!1},{text:"Water itself burns",correct:!1}],explanation:"Water on hot oil instantly turns to steam and spreads the burning oil (flash fire)."}]},{id:17,code:"MIL-117",icon:"Heart",accent:"#db2777",title:"First Aid and CPR",subtitle:"First Aid & CPR — Complete Training",summary:"Complete training in first aid, cardiopulmonary resuscitation (CPR) and emergency response on military bases",blocks:[{body:"First aid is the initial help given to an injured or sick person before medical teams arrive. On military bases the risk of injury is very high, from combat and blast wounds to electric shock and falls. Every Peshmerga must know how to perform CPR, stop bleeding, and protect the casualty until the ambulance (122) arrives."},{heading:"1. CPR: Cardiopulmonary Resuscitation (in Detail)",body:"CPR is a life-saving procedure for when a person's heart or breathing stops:",points:["1. Scene safety: make sure the casualty's location is safe (no explosives, fire or gas?).",'2. Responsiveness: tap their shoulders and ask loudly: "Are you all right? Can you hear me?"',"3. Call 122: if there is no response and no normal breathing (check for less than 10 seconds), call 122 immediately and get an AED.","4. Chest compressions: 30 compressions in the center of the chest; depth: 5-6 cm, rate: 100-120 compressions per minute.","5. Rescue breaths: tilt the head back and lift the chin, pinch the nose, and give 2 breaths of 1 second each. If you are not trained, or not willing to give breaths, give chest compressions only (Hands-Only CPR), without stopping.","6. Continue (30:2): until the ambulance (122) arrives or the casualty is breathing normally.","7. AED: as soon as it arrives, switch it on, attach the pads to the chest and follow the device's voice prompts."]},{heading:"2. Bleeding Control",body:"Severe bleeding can kill a person in a short time:",points:["Direct pressure: place a clean cloth on the wound and press firmly. If the cloth becomes soaked with blood, do not remove it: put another cloth on top.","Wound packing: for deep wounds in the neck, armpit or groin, pack the wound with gauze and apply pressure.","Tourniquet: use it early for life-threatening bleeding from an arm or leg, 5-7 cm above the wound; write down the time and never loosen it.","Impaled object: if metal, glass or blast fragments are lodged in the wound, do not pull them out! Stabilize the area around the object."]},{heading:"3. Burn Treatment",body:"Burns in the field and on bases:",points:["Thermal burns: pour cool running water over the burned area for 20 minutes (not ice).","Chemical burns: first gently brush off any dry powder, then rinse with plenty of water for 20 minutes.","Electrical burns: first cut off the power! Then treat as a thermal burn, and call 122.","Do not burst burn blisters; do not use oil, creams or toothpaste."]},{heading:"4. Fractures and Spinal Injuries",body:"After a fall:",points:["Splinting: do not move the injured limb; immobilize it with a piece of wood.","Spinal protection: if someone has fallen from a height, do not move them; keep them still and call 122. Move them only if the place is unsafe (fire, traffic, collapse, gas, rising water), keeping the head, neck and back in line. If they need CPR, lay them on their back on a firm surface. Do not put them on their side (recovery position).","Cooling: wrap ice in a cloth and place it on the painful area (not directly on the skin)."]},{heading:"5. Electric Shock and Rescue",body:"Electricity can stop the heart:",points:["Cut off the power immediately! Do not touch the casualty until the power has been cut off.","If you cannot cut it off and it is low voltage: use a dry piece of wood or plastic to separate the wire from the casualty. Do not approach high voltage, and call 115.","Everyone who has had an electric shock must go to hospital (122)."]}],media:[{kind:"video",src:"media/videos/mil_cpr.mp4",title:"CPR and First Aid",description:"CPR training for Peshmerga"}],quiz:[{question:"In CPR, how many chest compressions should be given per minute?",options:[{text:"50-70",correct:!1},{text:"80-90",correct:!1},{text:"100-120",correct:!0},{text:"150+",correct:!1}],explanation:"100-120 compressions per minute."},{question:"If a sharp object is lodged in a wound, what will you do?",options:[{text:"Pull it out",correct:!1},{text:"Leave it in place and call 122",correct:!0},{text:"Not touch it, and leave the casualty and go",correct:!1},{text:"Wash it with water and pull it out",correct:!1}],explanation:"Pulling the object out will increase the bleeding; stabilize the area around it and call 122."},{question:"If someone has had an electric shock, what is the first action?",options:[{text:"Take hold of their hand",correct:!1},{text:"Start CPR",correct:!1},{text:"Cut off the power",correct:!0},{text:"Pour water on them",correct:!1}],explanation:"The power must be cut off first."}]}],t={lessons:e};export{t as default,e as lessons};
